        // WilkinsonPlus (n odd ≥ 3): the two largest eigenvalues form a near-pair. n = 7:
        // reference eig ≈ {3.7616, 3.7321, 2.3633, …} ⇒ top gap ≈ 0.0295, next gap ≈ 1.37.
        void WilkinsonNearPair()
        {
